"""Human/native-agent entrypoint; every scientific process has a budget receipt."""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path
import subprocess
import sys

from compute import ROOT, dump, execute, ledger, now

PYTHON = str(ROOT/".venv/bin/python")
CAMPAIGN = ROOT/"campaigns/ema-v1"


def read(path):
    return json.loads(Path(path).read_text())


def sha(path):
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def helper():
    lock=read(CAMPAIGN/"lock.yaml" if CAMPAIGN.exists() else ROOT/".allagma/lock.yaml")
    return str(ROOT/".allagma/bundles"/lock["bundle_id"]/"tools/allagma.py")


def command(operation, *extras):
    return [PYTHON,helper(),"campaign",operation,"--study",str(ROOT),"--campaign","ema-v1",*extras]


def records():
    return [(p,read(p)) for p in sorted(CAMPAIGN.glob("runs/*/attempts/*/record.json"))]


def next_run():
    success={r["run_id"] for _,r in records() if r["status"]=="succeeded"}
    return next((r for r in read(CAMPAIGN/"protocol.json")["runs"] if r["id"] not in success),None)


def freeze():
    path=ROOT/"confirmation-freeze.json"
    if path.exists():
        raise RuntimeError("Freeze already exists; never overwrite it")
    successful=[(p,r) for p,r in records() if r["split"]=="pilot" and r["status"]=="succeeded"]
    if len(successful)!=4 or any(CAMPAIGN.glob("runs/confirm-*/attempts/*/started.json")):
        raise RuntimeError("Exactly four completed pilots and untouched confirmation are required")
    checks=[e for e in ledger()["entries"] if e["label"].startswith("known-answer")]
    if not checks or checks[-1].get("exit_code")!=0:
        raise RuntimeError("Known-answer checks must pass")
    times=[r["usage"]["wall_seconds"] for _,r in successful]
    forecast=max(times)*10*1.15+120
    available=ledger()["remaining_seconds"]
    if forecast>available:
        raise RuntimeError(f"Pilot-based confirmation forecast {forecast:.1f}s exceeds {available:.1f}s left; request a consequential decision before any budget change")
    protocol=read(CAMPAIGN/"protocol.json")
    for _,record in successful:
        for reference in record["inputs"]+record["outputs"]:
            if sha(ROOT/reference["path"])!=reference["sha256"]:
                raise RuntimeError("Pilot evidence changed")
    dump(path,{"frozen_at":now(),"protocol_revision":protocol["revision"],"protocol_sha256":sha(CAMPAIGN/"protocol.json"),
        "lock_sha256":sha(CAMPAIGN/"lock.yaml"),"decision":"Proceed unchanged after four qualified pilots; no confirmation result observed",
        "pilot_records":[{"path":str(p.relative_to(ROOT)),"sha256":sha(p)} for p,_ in successful],
        "code":{name:sha(CAMPAIGN/"materials"/name) for name in protocol["code"]},
        "orchestration":{name:sha(ROOT/name) for name in ("manage.py","compute.py","native_session.py","verify_results.py")},
        "pilot_attempt_seconds":times,"remaining_seconds_at_freeze":available,
        "forecast_seconds":forecast,"forecast_basis":"10 × longest pilot × 1.15 + 120s analysis/reproduction reserve",
        "confirmation_seeds":{name:[r["input"]["seed"] for r in protocol["runs"] if r["split"]=="confirmation" and r["input"]["dataset"]==name] for name in ("moons","gmm8")}})
    print(path.read_text())


def main():
    parser=argparse.ArgumentParser()
    parser.add_argument("operation",choices=["start","check","interrupt","pilot","freeze","confirm","analyze","audit","verify","status"])
    args=parser.parse_args()
    if args.operation=="status":
        value={k:v for k,v in ledger().items() if k!="entries"}
        if CAMPAIGN.exists():
            value.update(state=read(CAMPAIGN/"state.json"),next_run=next_run())
        print(json.dumps(value,indent=2))
        return 0
    if args.operation=="start":
        return subprocess.call(command("start"),cwd=ROOT)
    if args.operation=="check":
        return execute("known-answer-final",[PYTHON,str(ROOT/"domain/test_science.py")],30)
    if args.operation=="freeze":
        freeze()
        return 0
    if args.operation=="verify":
        return execute("independent-verification",[PYTHON,str(ROOT/"verify_results.py")],120)
    if args.operation in ("interrupt","pilot","confirm"):
        run=next_run()
        if run is None:
            print("All declared trajectories already complete")
            return 0
        phase="confirmation" if args.operation=="confirm" else "pilot"
        if run["split"]!=phase:
            raise RuntimeError(f"Next run is {run['split']}; use the correct phase command")
        if phase=="confirmation" and not (ROOT/"confirmation-freeze.json").is_file():
            raise RuntimeError("Post-pilot confirmation freeze is required")
        extras=["--stop-after","1"]
        if args.operation=="interrupt":
            extras += ["--fault-run",run["id"],"--fault-mode","interrupt"]
        return execute(args.operation+"-"+run["id"],command("run",*extras),160,attempt=True)
    return execute(args.operation,command(args.operation),120)


if __name__=="__main__":
    raise SystemExit(main())
"""Serial, crash-conservative wall-time accounting for all study computation.

Environment installation, source editing and model deliberation are not study
computation. Scientific checks, training, sampling, evaluation, analysis and
recomputation are. Launch those only through this supervisor.
"""
from __future__ import annotations

import datetime
import fcntl
import json
import os
from pathlib import Path
import signal
import subprocess
import sys
import time

ROOT = Path(__file__).resolve().parent
CEILING = 1800.0
ATTEMPTS = 18


def now():
    return datetime.datetime.now(datetime.timezone.utc).isoformat()


def dump(path, obj):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    temp = path.with_suffix(path.suffix+".tmp")
    temp.write_text(json.dumps(obj, sort_keys=True, indent=2, allow_nan=False)+"\n")
    temp.replace(path)


def ledger():
    directory = ROOT/"evidence/compute"
    entries = [json.loads(p.read_text()) for p in sorted(directory.glob("*.json"))]
    charged = 15.3  # Conservatively include the user-reported pre-goal estimate.
    for entry in entries:
        charged += entry.get("charged_seconds", entry["reservation_seconds"])
    return {"ceiling_seconds": CEILING, "prior_probe_estimate_charged_seconds": 15.3,
            "prior_probe_is_scientific_evidence": False,
            "charged_seconds": charged, "remaining_seconds": max(0., CEILING-charged),
            "attempt_limit": ATTEMPTS, "attempts": sum(e["attempt"] for e in entries), "entries": entries}


def execute(label, command, limit, *, attempt=False):
    (ROOT/"evidence/compute").mkdir(parents=True, exist_ok=True)
    with (ROOT/"evidence/compute.lock").open("a") as mutex:
        fcntl.flock(mutex, fcntl.LOCK_EX | fcntl.LOCK_NB)
        current = ledger()
        if current["remaining_seconds"] < limit+2:
            raise RuntimeError(f"Insufficient compute reserve: {current['remaining_seconds']:.2f}s left; need {limit+2:.2f}s")
        if attempt and current["attempts"] >= ATTEMPTS:
            raise RuntimeError("Study-wide attempt ceiling reached")
        index = len(current["entries"])+1
        stem = f"{index:03d}-{label}"
        record = ROOT/"evidence/compute"/(stem+".json")
        event = {"label": label, "command": command, "cwd": str(ROOT), "attempt": bool(attempt),
                 "started_at": now(), "reservation_seconds": limit+2, "timeout_seconds": limit,
                 "status": "running", "pid": os.getpid()}
        dump(record, event)
        started = time.monotonic()
        process = None
        try:
            env = {**os.environ, "OMP_NUM_THREADS": "1", "OPENBLAS_NUM_THREADS": "1", "MKL_NUM_THREADS": "1",
                   "MPLCONFIGDIR": str(ROOT/".cache/matplotlib"), "PYTORCH_ENABLE_MPS_FALLBACK": "0",
                   "ALLAGMA_STUDY_COMPUTE_RECEIPT": str(record)}
            with record.with_suffix(".stdout.txt").open("w") as out, record.with_suffix(".stderr.txt").open("w") as err:
                process = subprocess.Popen(command, cwd=ROOT, env=env, stdout=out, stderr=err, start_new_session=True)
                event["child_pid"] = process.pid
                dump(record, event)
                try:
                    code = process.wait(timeout=limit)
                    event["status"] = "completed" if code == 0 else "failed"
                except subprocess.TimeoutExpired:
                    os.killpg(process.pid, signal.SIGTERM)
                    try:
                        process.wait(timeout=.5)
                    except subprocess.TimeoutExpired:
                        os.killpg(process.pid, signal.SIGKILL)
                        process.wait()
                    code = 124
                    event["status"] = "timeout"
        except BaseException:
            # Reserve the whole timeout on uncertainty, including any bounded
            # Allagma worker in a separate process group. Never infer zero cost.
            event.update(status="uncertain", ended_at=now())
            dump(record, event)
            raise
        else:
            event.update(exit_code=code, ended_at=now(), charged_seconds=time.monotonic()-started)
            dump(record, event)
            dump(ROOT/"evidence/compute-summary.json", {k:v for k,v in ledger().items() if k != "entries"})
            print(json.dumps({"receipt": str(record.relative_to(ROOT)), **event}, indent=2))
            if code:
                print(record.with_suffix(".stderr.txt").read_text()[-6000:], file=sys.stderr)
            return code


if __name__ == "__main__":
    print(json.dumps(ledger(), indent=2))
"""Publish a disclosed manuscript with exact, recomputable draft provenance.

The frozen study writer remains the source of all scientific content. This
separate reporting step adds the required AI disclosure and relocates links.
"""
import hashlib
import json
import os
from pathlib import Path
import re
import sys

from compute import ROOT, execute

DISCLOSURE=("**Disclosure.** This study's code, analysis, figures and manuscript were "
    "machine-generated with OpenAI Codex, using an adaptation of SakanaAI/AI-Scientist's "
    "pinned 2D diffusion template. Measurements come from retained local MPS executions. "
    "No independent scientific peer review is claimed.\n\n")


def reference(path, media="application/json"):
    return {"path":path.relative_to(ROOT).as_posix(),"sha256":hashlib.sha256(path.read_bytes()).hexdigest(),
            "media_type":media,"retention":"retain-with-study"}


def content(source,destination):
    original=source.read_text()
    def relocate(match):
        target=match.group(2)
        if "://" in target or target.startswith("#"):
            return match.group(0)
        actual=(source.parent/target).resolve()
        if not actual.is_relative_to(ROOT) or not actual.is_file():
            raise ValueError("Broken or external local manuscript link: "+target)
        return f"[{match.group(1)}]({os.path.relpath(actual,destination.parent)})"
    relocated=re.sub(r"\[([^\]]*)\]\(([^)]+)\)",relocate,original)
    heading,body=relocated.split("\n\n",1)
    return heading+"\n\n"+DISCLOSURE+body


def publish():
    source=ROOT/"campaigns/ema-v1/analyses/a001/paper/manuscript.md"
    directory=ROOT/"publication"
    directory.mkdir(exist_ok=False)
    destination=directory/"manuscript.md"
    destination.write_text(content(source,destination))
    # Independently repeat the deterministic text transformation before receipt.
    assert destination.read_text()==content(source,destination)
    report={"status":"pass","transformation":"Prepend machine-generation disclosure after title; rebase local Markdown links; preserve all remaining scientific wording and numbers",
            "source":reference(source,"text/markdown"),"output":reference(destination,"text/markdown"),
            "script":reference(Path(__file__).resolve(),"text/x-python"),
            "disclosure":reference(ROOT/"DISCLOSURE.md","text/markdown"),
            "analysis":reference(ROOT/"campaigns/ema-v1/analyses/a001/record.json"),
            "claims":reference(ROOT/"campaigns/ema-v1/analyses/a001/paper/claims.json"),
            "scope":"Publication text transformation and local link verification; scientific recomputation is separately established by campaign audit and independent verification"}
    (directory/"record.json").write_text(json.dumps(report,sort_keys=True,indent=2)+"\n")
    print(json.dumps(report,indent=2))


if __name__=="__main__":
    if sys.argv[1:]==["--worker"]:
        publish()
    elif not sys.argv[1:]:
        raise SystemExit(execute("publication",[str(ROOT/".venv/bin/python"),str(Path(__file__).resolve()),"--worker"],15))
    else:
        raise SystemExit("Use publication.py without arguments for the budgeted publication step")

